CREATE TABLE IF NOT EXISTS world_boss_season (id BIGINT NOT NULL AUTO_INCREMENT, season_key VARCHAR(32) NOT NULL, boss_name VARCHAR(64) NOT NULL, law_name VARCHAR(64) NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_world_boss_season(season_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS world_boss_run (id BIGINT NOT NULL AUTO_INCREMENT, run_key VARCHAR(16) NOT NULL, boss_name VARCHAR(64) NOT NULL, max_hp BIGINT NOT NULL, current_hp BIGINT NOT NULL, law_name VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_world_boss_run(run_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS world_boss_contribution (id BIGINT NOT NULL AUTO_INCREMENT, run_id BIGINT NOT NULL, uid INT NOT NULL, action_type VARCHAR(16) NOT NULL, damage BIGINT NOT NULL DEFAULT 0, support BIGINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY idx_world_boss_user(run_id, uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS world_boss_reward_log (id BIGINT NOT NULL AUTO_INCREMENT, run_id BIGINT NOT NULL, uid INT NOT NULL, reward_tier VARCHAR(16) NOT NULL, reward_lingshi INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_world_boss_reward(run_id, uid, reward_tier)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
